<?php
$root=$argv[1];$url=getenv('FIXTURE_URL');$_SERVER['HTTP_HOST']=parse_url($url,PHP_URL_HOST).':'.parse_url($url,PHP_URL_PORT);require $root.'/wp-load.php';require_once ABSPATH.'wp-admin/includes/plugin.php';wp_set_current_user(1);
if($argv[2]==='activate'){$result=activate_plugin('contact-form-7/wp-contact-form-7.php');if(is_wp_error($result))throw new RuntimeException($result->get_error_message());echo "Activated Contact Form 7\n";exit;}
if(!class_exists('WPCF7_ContactForm'))throw new RuntimeException('Contact Form 7 did not initialize');
foreach(WPCF7_ContactForm::find(['posts_per_page'=>-1]) as $form)wp_delete_post($form->id(),true);
$definitions=[
 'contact'=>['Contact','<p><label>Your name [text* your-name autocomplete:name]</label></p><p><label>Email [email* your-email autocomplete:email]</label></p><p><label>Message [textarea* your-message minlength:10 maxlength:500]</label></p><p>[acceptance terms]I accept the contact terms.[/acceptance]</p><p>[submit "Send message"]</p>'],
 'quote'=>['Request a quote','<p><label>Work email [email* work-email]</label></p><p><label>Quantity [number* quantity min:1 max:10]</label></p><p><label>Preferred date [date* preferred-date min:2027-01-01 max:2027-12-31]</label></p><fieldset><legend>Services (choose at least one)</legend>[checkbox* services use_label_element "Planning" "Design"]</fieldset><fieldset><legend>Reply channel</legend>[radio channel use_label_element default:1 "Email" "Phone"]</fieldset><p><label>Region [select* region first_as_label "Choose a region" "North" "South"]</label></p><p><label>Attachment [file attachment limit:2mb filetypes:pdf|txt]</label></p><p>[acceptance agreement]I agree to the quote terms.[/acceptance]</p><p>[submit "Request quote"]</p>']
];
$records=[];
foreach($definitions as $slug=>$definition){$form=WPCF7_ContactForm::get_template();$form->set_title($definition[0]);$form->set_properties(['form'=>$definition[1]]);$id=$form->save();if(!$id)throw new RuntimeException('Could not save form');$page=get_page_by_path($slug);$content='<h2>'.$definition[0].'</h2><p>Local fixture only. No messages are delivered.</p>[contact-form-7 id="'.$id.'" title="'.$definition[0].'"]';$pageid=wp_insert_post(['ID'=>$page?$page->ID:0,'post_type'=>'page','post_status'=>'publish','post_title'=>$definition[0],'post_name'=>$slug,'post_content'=>$content]);$records[]=['id'=>$id,'slug'=>$slug,'url'=>get_permalink($pageid)];}
flush_rewrite_rules();file_put_contents(dirname($root).'/form-records.json',json_encode(['forms'=>$records],JSON_PRETTY_PRINT));echo json_encode(['forms'=>$records],JSON_PRETTY_PRINT)."\n";
